"range":{"stats":{"field":"@timestamp"}},
"bytes":{"stats":{"field":"bytes"}}
}}' | python3 -c "import json,sys; d=json.load(sys.stdin); print('total', d['hits']['total']); print(json.dumps(d['aggregations'],indent=1))"

